import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = Lp.max()
    l1 = s * s
    if linf <= 0 or l1 <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    h = np.maximum(h, 0.0)
    if h.size == N:
        return h.copy()
    if h.size == 0:
        return np.ones(N)
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(N) + 0.5) / N
    return np.maximum(np.interp(x_new, x_old, h), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    N = 200

    if start is not None and np.asarray(start).size > 0:
        h0 = _resample(start, N)
        if h0.sum() <= 0:
            h0 = np.concatenate([np.ones(100), 2.0 * np.ones(100)])
    else:
        h0 = np.concatenate([np.ones(100), 2.0 * np.ones(100)])

    best_h = h0.copy()
    best_R = _R(best_h)
    cur = h0.copy()
    cur_R = best_R

    rng = np.random.default_rng(987654321)
    idx = np.arange(N)
    step = 0.15

    # Precompute convolution cost budget: each _R is O(N^2). N=200 -> cheap.
    while time.process_time() < deadline:
        improved_any = False
        rng.shuffle(idx)
        for i in idx:
            if time.process_time() >= deadline:
                break
            base_val = cur[i]
            if base_val <= 1e-15:
                base_val = 1e-12
            best_local = cur_R
            best_val = cur[i]
            for factor in (np.exp(step), np.exp(-step),
                           np.exp(step * 0.5), np.exp(-step * 0.5)):
                trial_val = base_val * factor
                if trial_val <= 0:
                    continue
                old = cur[i]
                cur[i] = trial_val
                r = _R(cur)
                if r > best_local:
                    best_local = r
                    best_val = trial_val
                cur[i] = old
            if best_local > cur_R:
                cur[i] = best_val
                cur_R = best_local
                improved_any = True
                if cur_R > best_R:
                    best_R = cur_R
                    best_h = cur.copy()

        if not improved_any:
            step *= 0.9

        if step < 5e-4:
            # Restart with perturbation from best; occasionally big jump
            if rng.random() < 0.3:
                cur = best_h * np.exp(rng.normal(0, 0.08, size=N))
            else:
                cur = best_h * np.exp(rng.normal(0, 0.02, size=N))
            cur = np.maximum(cur, 0.0)
            cur_R = _R(cur)
            if cur_R > best_R:
                best_R = cur_R
                best_h = cur.copy()
            step = 0.15

    return best_h

import numpy as np
import time


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or h.max() <= 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    q = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    m = L.max()
    if m <= 0:
        return -1.0
    return q / (s * s * m)


def _score_grad(h):
    """Return (R, dR/dh) for the step-function autoconvolution objective."""
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    conv = np.convolve(h, h)          # length 2n-1
    L = np.concatenate(([0.0], conv, [0.0]))  # length 2n+1
    q = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    m = L.max()
    if m <= 0 or s <= 0:
        return -1.0, np.zeros(n)
    R = q / (s * s * m)
    # dq/dL_j = (2 L_j + L_{j+1} + L_{j-1}) / 3
    dq_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    # L_j corresponds to conv_{j-1}; conv_k = sum_i h_i h_{k-i}
    # dq/dh_i = sum_k dq_dL[k+1] * 2 h_{k-i}
    dq_dconv = dq_dL[1:-1]            # length 2n-1
    # gradient of q wrt h: 2 * correlation
    g_q = 2.0 * np.convolve(dq_dconv, h[::-1])[n - 1:2 * n - 1]
    # dR/dh = g_q/(s^2 m) - q*(2 s m + s^2 * dm/dh)/(s^4 m^2)
    # dm/dh = derivative of max: distribute to argmax knot
    k = int(np.argmax(L))
    dm = np.zeros(n)
    if 1 <= k <= 2 * n - 1:
        kk = k - 1
        # conv_kk = sum_i h_i h_{kk-i}; contributes 2 h_{kk-i}
        for i in range(n):
            j = kk - i
            if 0 <= j < n:
                dm[i] += 2.0 * h[j]
    g = g_q / (s * s * m) - q * (2.0 * s * m + s * s * dm) / (s ** 4 * m * m)
    return R, g


def _resample(h, n):
    m = h.size
    if m == n:
        return h.copy()
    x_old = (np.arange(m) + 0.5) / m
    x_new = (np.arange(n) + 0.5) / n
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def remaining():
        return deadline - time.process_time()

    # ---- initial candidate ----
    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        if best.ndim != 1 or best.size == 0:
            best = np.ones(50)
    else:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    bestR = _score(best)

    def consider(h):
        nonlocal best, bestR
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.sum() <= 0:
            return
        r = _score(h)
        if r > bestR:
            bestR = r
            best = h.copy()

    # ---- gradient ascent polish (L-BFGS-free: plain projected ascent w/ adaptation) ----
    def grad_ascent(h0, steps, lr0):
        h = np.maximum(np.asarray(h0, dtype=float), 0.0)
        R, g = _score_grad(h)
        lr = lr0
        for _ in range(steps):
            if time.process_time() > deadline:
                break
            gn = np.linalg.norm(g)
            if gn < 1e-14:
                break
            # scale step relative to h magnitude
            step = lr * h.max() / (gn + 1e-30) * g
            hn = np.maximum(h + step, 0.0)
            Rn, gn_vec = _score_grad(hn)
            if Rn > R:
                h, R, g = hn, Rn, gn_vec
                lr *= 1.15
            else:
                lr *= 0.5
                if lr < 1e-9:
                    break
        return h, R

    # ---- refine at increasing resolutions using gradient ascent ----
    # Start from current best; progressively upsample and polish.
    resolutions = [best.size]
    for n in [200, 400, 800, 1600, 3200, 6400, 12800]:
        if n > best.size:
            resolutions.append(n)
    resolutions = sorted(set(resolutions))

    for n in resolutions:
        if remaining() < 1.0:
            break
        h0 = _resample(best, n)
        h1, r1 = grad_ascent(h0, steps=400, lr0=0.5)
        if r1 > bestR:
            bestR = r1
            best = h1

    # ---- alternating large-scale gradient polish on the final resolution ----
    while remaining() > 0.5:
        h1, r1 = grad_ascent(best, steps=100, lr0=0.2)
        if r1 > bestR:
            bestR = r1
            best = h1
        else:
            # small random restart perturbation
            h = best + np.random.default_rng().normal(0, 0.01 * best.max(), best.size)
            h = np.maximum(h, 0.0)
            consider(h)
            break

    print(f"final R estimate {bestR:.9f}, N={best.size}")
    return best
